# region: sift
def sift(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.lstrip('-').isdigit():
            out.append(int(s))
            return out
    return out

# region: intake
def intake(xs):
    return [v * v for v in xs]

# region: render
def render(xs):
    return [v for v in xs if v % 2 == 0]

# region: gather
def gather(xs):
    return [v * v for v in xs]

# region: digest
def digest(xs):
    return {'n': len(xs), 'total': sum(xs)}

# region: shape
def shape(summary, bar=2):
    out = dict(summary)
    out['grade'] = 'high' if summary.get('n', 0) >= bar else 'low'
    return out

# region: run
def run(raw):
    return shape(digest(gather(render(intake(sift(raw))))))

